import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side':..., 'price':..., 'qty':..., 'active':bool}
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    def match_incoming(incoming_id, side, price, qty):
        # price is None for market orders (match any price)
        nonlocal trades
        if side == 'buy':
            heap = sell_heap
            while qty > 0 and heap:
                p, s, oid = heap[0]
                info = book.get(oid)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if price is not None and p > price:
                    break
                trade_qty = min(qty, info['qty'])
                trades.append([incoming_id, oid, p, trade_qty])
                qty -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(heap)
            return qty
        else:
            heap = buy_heap
            while qty > 0 and heap:
                negp, s, oid = heap[0]
                p = -negp
                info = book.get(oid)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if price is not None and p < price:
                    break
                trade_qty = min(qty, info['qty'])
                trades.append([oid, incoming_id, p, trade_qty])
                qty -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(heap)
            return qty

    for seq, order in enumerate(orders):
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(oid, side, price, qty)
            if remaining > 0:
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq, oid))
            else:
                # fully filled, mark as inactive record (not resting)
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(oid, side, price, qty)
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}
        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(oid, side, None, qty)
            book[oid] = {'side': side, 'price': None, 'qty': 0, 'active': False}
        elif typ == 'cancel':
            _, oid = order
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False

    return trades

